// js
const employment = ctx.subject.employment;
const terms = employment.terms;
const extension = get(employment, 'employee_extension_data', {});
const ordinary_wages = Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const total = Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', ordinary_wages));
const bonus = Math.max(0, total - ordinary_wages);
if (total <= 0) return 0;
const residency = get(terms, 'residency_status', null);
if (residency == null)
	throw 'Record the tax residence on the sealed contract (CITIZEN, PERMANENT_RESIDENT, RESIDENT or NON_RESIDENT); Vietnamese law presumes neither residence nor non-residence.';
const allowance = (code) => Number(get(terms, 'allowances.' + code + '.amount', 0));
const meal = allowance('MEAL_ALLOWANCE');
const housing = allowance('HOUSING');
const pension = allowance('EMPLOYER_PENSION_CONTRIBUTION');
const voluntaryPension = Number(
	get(extension, 'facts.statutory.PIT.elections.voluntary_pension_contribution', 0)
);
const workExpense = allowance('WORK_EXPENSE_ALLOWANCE');
const fixedMealCap = ctx.lookup.meal_allowance_cap;
const mealCap =
	fixedMealCap == null
		? get(extension, 'term_facts.cash_meal_policy_limit_vnd', null)
		: Number(fixedMealCap);
if (mealCap == null && meal > 0)
	throw 'Record the documented cash-meal policy limit for this pay month.';
const ordinary = Math.max(0, ordinary_wages - meal - housing - pension - workExpense);
const taxableMeal = Math.max(0, meal - Number(mealCap ?? 0));
const housingCap =
	ctx.lookup.housing_exempt_ratio * (ordinary + taxableMeal + Math.max(0, pension));
const taxableHousing = Math.max(0, Math.min(housing, housingCap));
const employerLimit = Number(
	get(ctx.subject.employer.entity_extension_data, 'work_expense_limit', 0)
);
const taxableWorkExpense = Math.max(0, workExpense - employerLimit);
const taxablePension = Math.max(0, pension + voluntaryPension - ctx.lookup.pension_cap);
const remuneration =
	ordinary + taxableMeal + taxableHousing + taxablePension + taxableWorkExpense + bonus;
const signed = get(employment, 'signed_contract_period', null);
const shortTerm =
	signed != null &&
	signed.to != null &&
	add_months(signed.from, ctx.lookup.short_term_months) > signed.to;
const resident = residency !== 'NON_RESIDENT';
const insurance =
	Number(get(get(ctx.statutory, 'SI', {}), 'employee', 0)) +
	Number(get(get(ctx.statutory, 'HI', {}), 'employee', 0)) +
	Number(get(get(ctx.statutory, 'UI', {}), 'employee', 0));
if (get(terms, 'employer_bears_income_tax', false) === true) return 0;
if (shortTerm)
	return remuneration >= ctx.lookup.short_term_threshold
		? remuneration * ctx.lookup.short_term_rate
		: 0;
if (!resident) return remuneration * ctx.lookup.non_resident_rate;
const period = String(get(ctx.run, 'period', ctx.as_of.substring(0, 7)));
const year = period.substring(0, 4);
const prior = get(ctx.history, 'payslips', []).filter((slip) => {
	const key = String(get(slip, 'period', ''));
	return key !== '' && key <= period && key.substring(0, 4) === year;
});
const periods = prior.reduce(
	(list, slip) => {
		const key = String(get(slip, 'period', ''));
		return list.includes(key) ? list : [...list, key];
	},
	[period]
);
const months = periods.length;
const priorGross = sum(prior.map((slip) => Number(get(slip, 'gross_earnings', 0))));
const priorInsurance = sum(prior.map((slip) => Number(get(slip, 'employee_statutory', 0))));
const priorTax = sum(prior.map((slip) => Number(get(slip, 'tax_withheld', 0))));
const monthlyDeduction =
	ctx.lookup.personal_deduction +
	ctx.lookup.dependant_deduction *
		Number(get(extension, 'facts.statutory.PIT.elections.dependants', 0));
const assessable = Math.max(
	0,
	priorGross + remuneration - priorInsurance - insurance - monthlyDeduction * months
);
const annual = ctx.lookup.brackets.map((row) => ({
	up_to: row.up_to == null ? null : Number(row.up_to) * 12,
	rate: row.rate
}));
// Monthly withholding is non-negative; an excess is credited in the annual finalisation.
return Math.max(0, ladder(assessable, annual) - priorTax);

